import React, { useRef, useState } from 'react';
import { Tour, Button } from '@salutejs/sdds-finai';
export function App() {
    const ref1 = useRef(null);
    const ref2 = useRef(null);
    const [open, setOpen] = useState(false);
    const [current, setCurrent] = useState(0);
    const onClose = () => { setOpen(false); setCurrent(0); };
    const steps = [
        { target: ref1, title: 'Первый шаг', description: 'Начало тура.' },
        { target: ref2, title: 'Второй шаг', description: 'Завершение тура.', placement: 'top' },
    ];
    const renderStep = (cur, length, last, step, goToStep) => (
        <div style={{ padding: '1rem', background: 'var(--surface-solid-card)', borderRadius: '0.75rem', boxShadow: '0 4px 16px rgba(0,0,0,0.12)', maxWidth: '16rem', display: 'flex', flexDirection: 'column', gap: '0.5rem' }}>
            {step.title && <strong>{step.title}</strong>}
            {step.description && <small style={{ opacity: 0.7 }}>{step.description}</small>}
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <div style={{ display: 'flex', gap: '0.5rem' }}>
                    {cur > 0 && <Button size="s" view="secondary" onClick={() => goToStep(cur - 1)}>Назад</Button>}
                    {last
                        ? <Button size="s" view="default" onClick={onClose}>Закрыть</Button>
                        : <Button size="s" view="default" onClick={() => goToStep(cur + 1)}>Далее</Button>
                    }
                </div>
                <small>{cur + 1} / {length}</small>
            </div>
        </div>
    );
    return (
        <div style={{ padding: '2rem', display: 'flex', flexDirection: 'column', gap: '6rem' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                <Button ref={ref1} view="secondary">Элемент 1</Button>
                <Button ref={ref2} view="secondary">Элемент 2</Button>
            </div>
            <Button view="default" onClick={() => setOpen(true)}>Запустить тур</Button>
            <Tour
                open={open}
                current={current}
                onChange={setCurrent}
                onClose={onClose}
                steps={steps}
                renderStep={renderStep}
                highlightBorderRadius="1rem"
            />
        </div>
    );
}

