        <div style={{ padding: '2rem', display: 'flex', flexDirection: 'column', gap: '4rem' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                <Button ref={ref1} view="secondary">Элемент 1</Button>
                <Button ref={ref2} view="secondary">Элемент 2</Button>
            </div>
            <Tour defaultOpen defaultCurrent={0} steps={steps} renderStep={renderStep} />
        </div>
    );
}

import React, { useRef, useState } from 'react';
import { Tour, Button, TextField, Switch } from '@salutejs/sdds-finai';
export function App() {
    const textFieldRef = useRef(null);
    const switchRef = useRef(null);
    const buttonRef = useRef(null);
    const [open, setOpen] = useState(false);
    const [current, setCurrent] = useState(0);
    const [name, setName] = useState('');
    const [checked, setChecked] = useState(false);
    const onClose = () => { setOpen(false); setCurrent(0); };
    const steps = [
        { target: textFieldRef, title: 'Имя пользователя', description: 'Введите имя для профиля.' },
        { target: '#custom-highlight-switch', title: 'Уведомления', description: 'Включите push-уведомления.', placement: 'left' },
        { target: buttonRef, title: 'Сохранить', description: 'Примените все изменения.', placement: 'top' },
    ];
    const renderHighlight = ({ left, top, width, height, borderRadius }) => (
        <div
            style={{
                position: 'fixed',
                left,
                top,
                width,
                height,
                borderRadius,
                background: 'rgba(0, 102, 255, 0.1)',
                animation: 'tour-doc-pulse 1.4s ease-in-out infinite',
                pointerEvents: 'none',
            }}
        />
    );
    const renderStep = (cur, length, last, step, goToStep) => (
        <div style={{ padding: '1rem', background: 'var(--surface-solid-card)', borderRadius: '0.75rem', boxShadow: '0 4px 16px rgba(0,0,0,0.12)', maxWidth: '16rem', display: 'flex', flexDirection: 'column', gap: '0.5rem' }}>
            {step.title && <strong>{step.title}</strong>}
            {step.description && <small style={{ opacity: 0.7 }}>{step.description}</small>}
            <div style={{ display: 'flex', gap: '0.5rem', marginTop: '0.25rem' }}>
                {cur > 0 && <Button size="s" view="secondary" onClick={() => goToStep(cur - 1)}>Назад</Button>}
                {last ? <Button size="s" view="default" onClick={onClose}>Закрыть</Button> : <Button size="s" view="default" onClick={() => goToStep(cur + 1)}>Далее</Button>}
            </div>
        </div>
    );
    return (
        <>
            <style>{`
                @keyframes tour-doc-pulse {
                    0%, 100% { box-shadow: 0 0 0 2px rgba(0,102,255,0.85), 0 0 0 6px rgba(0,102,255,0.2); }
                    50%       { box-shadow: 0 0 0 3px rgba(0,102,255,0.35), 0 0 0 12px rgba(0,102,255,0); }
                }
            `}</style>
            <div style={{ maxWidth: '24rem', padding: '2rem', display: 'flex', flexDirection: 'column', gap: '1.5rem' }}>
                <div ref={textFieldRef}>
                    <TextField label="Имя пользователя" value={name} onChange={(e) => setName(e.target.value)} />
                </div>
                <Switch id="custom-highlight-switch" label="Push-уведомления" checked={checked} onChange={(e) => setChecked(e.target.checked)} />
                <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                    <Button view="secondary" onClick={() => setOpen(true)}>Запустить тур</Button>
                    <Button ref={buttonRef} view="default">Сохранить</Button>
                </div>
                <Tour
                    open={open}
                    current={current}
                    onChange={setCurrent}
                    onClose={onClose}
                    steps={steps}
                    renderStep={renderStep}
                    withOverlay={false}
                    renderHighlight={renderHighlight}
                    highlightBorderRadius="1rem"
                />
            </div>
        </>
    );
}
